insert into public.knowledge_entries(doc_id,title,category,subcategory,summary,content,keywords,source_title,source_url,metadata,status,review_status,evidence_level)
select doc_id,title,'Penyakit Tanaman','Katalog referensi PM',summary,content,keywords,source_title,source_url,metadata,'published',
  'Ringkasan editorial berdasarkan publikasi pemerintah; belum divalidasi ahli.','Rujukan publik pemerintah; bukan pemeriksaan lapangan'
from jsonb_to_recordset('[{"doc_id":"PM-DISEASE-MOLER-001","title":"Moler / layu Fusarium","summary":"Perhatikan daun menguning dan terpelintir bersama kerusakan akar atau pangkal umbi, bukan hanya bentuk daun.","content":"# Moler / layu Fusarium\n\nPerhatikan daun menguning dan terpelintir bersama kerusakan akar atau pangkal umbi, bukan hanya bentuk daun.\n\nPenyebab: Fusarium oxysporum.\n\n## Gejala yang diamati\n- Daun menguning, terpelintir, lalu layu.\n- Akar rusak sehingga tanaman lebih mudah tercabut.\n- Pembusukan bermula dari dasar umbi; pertumbuhan cendawan putih dapat terlihat di pangkal.\n\n## Pencegahan\n- Gunakan bahan tanam sehat dan hindari melukai umbi.\n- Jaga drainase agar tanaman tidak tergenang.\n- Lakukan pergiliran dengan tanaman bukan inang.\n\n## Tindakan awal\n- Periksa akar dan pangkal umbi pada tanaman bergejala.\n- Singkirkan tanaman sakit dari pertanaman dan jangan gunakan umbinya sebagai benih.\n- Minta pendampingan POPT atau penyuluh untuk memastikan penyebab dan tindakan lanjutan.\n\n## Jangan tertukar\nDaun terpelintir saja tidak membuktikan moler. Amati akar serta dasar umbi dan bandingkan dengan gejala antraknosa.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Pengendalian penyakit layu Fusarium pada tanaman bawang merah](https://distankan.bulelengkab.go.id/informasi/detail/artikel/pengendalian-penyakit-layu-fusarium-pada-tanaman-bawang-merah-25) — Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng, 2020.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Fusarium oxysporum","aliases":["moler","ngoler","layu fusarium"],"parts":["Daun","Akar & umbi"],"symptoms":["Daun menguning, terpelintir, lalu layu.","Akar rusak sehingga tanaman lebih mudah tercabut.","Pembusukan bermula dari dasar umbi; pertumbuhan cendawan putih dapat terlihat di pangkal."],"prevention":["Gunakan bahan tanam sehat dan hindari melukai umbi.","Jaga drainase agar tanaman tidak tergenang.","Lakukan pergiliran dengan tanaman bukan inang."],"first_steps":["Periksa akar dan pangkal umbi pada tanaman bergejala.","Singkirkan tanaman sakit dari pertanaman dan jangan gunakan umbinya sebagai benih.","Minta pendampingan POPT atau penyuluh untuk memastikan penyebab dan tindakan lanjutan."],"confused_with":"Daun terpelintir saja tidak membuktikan moler. Amati akar serta dasar umbi dan bandingkan dengan gejala antraknosa.","sources":[{"title":"Pengendalian penyakit layu Fusarium pada tanaman bawang merah","publisher":"Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng","year":"2020","url":"https://distankan.bulelengkab.go.id/informasi/detail/artikel/pengendalian-penyakit-layu-fusarium-pada-tanaman-bawang-merah-25"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=29","label":"Gambar 12 · halaman tercetak 19 (PDF 29)","credit":"Soetiarso, dalam Udiarto, Setiawati & Suryaningsih, Balitsa (2005). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Moler / layu Fusarium","moler","ngoler","layu fusarium","Fusarium oxysporum"],"source_title":"Pengendalian penyakit layu Fusarium pada tanaman bawang merah","source_url":"https://distankan.bulelengkab.go.id/informasi/detail/artikel/pengendalian-penyakit-layu-fusarium-pada-tanaman-bawang-merah-25"},{"doc_id":"PM-DISEASE-BERCAK-UNGU-001","title":"Bercak ungu / trotol","summary":"Bercak pada daun berkembang menjadi keunguan dengan pola menyerupai cincin. Ujung daun dapat mengering dan patah.","content":"# Bercak ungu / trotol\n\nBercak pada daun berkembang menjadi keunguan dengan pola menyerupai cincin. Ujung daun dapat mengering dan patah.\n\nPenyebab: Alternaria porri.\n\n## Gejala yang diamati\n- Bercak awal putih atau kelabu dan tampak agak cekung.\n- Bercak membentuk cincin keunguan dengan daerah kekuningan di sekelilingnya.\n- Bagian daun di atas bercak dapat mengering dan patah.\n\n## Pencegahan\n- Pilih benih sehat, tidak keropos dan tidak terluka.\n- Perbaiki drainase serta lakukan pergiliran tanaman bukan inang.\n- Jaga kebersihan pertanaman dari sisa tanaman sakit.\n\n## Tindakan awal\n- Amati perubahan warna dan pola bercak, bukan warna daun secara keseluruhan saja.\n- Pisahkan bahan tanaman sakit dari bahan tanam sehat.\n- Bila serangan bertambah, konsultasikan pengendalian kepada POPT atau penyuluh; penggunaan pestisida harus sesuai label yang berlaku.\n\n## Jangan tertukar\nAntraknosa juga dapat menimbulkan bercak putih. Cincin keunguan merupakan petunjuk pembanding, bukan kepastian diagnosis.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Penyakit bercak ungu pada tanaman bawang merah dan pengendaliannya](https://distankan.bulelengkab.go.id/informasi/detail/artikel/penyakit-bercak-ungu-pada-tanaman-bawang-merah-dan-pengendaliannya-27) — Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng, 2020.\n- [Budidaya bawang merah · bagian penyakit penting](https://banten.brmp.pertanian.go.id/storage/assets/uploads/file/GeY2HQf382EJXVJsYRiE9ZwRfFwnHSw5fL8twqWy.pdf#page=5) — BRMP Banten, Kementerian Pertanian, tahun dokumen tidak tercantum pada rujukan yang ditinjau.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Alternaria porri","aliases":["bercak ungu","trotol","purple blotch"],"parts":["Daun"],"symptoms":["Bercak awal putih atau kelabu dan tampak agak cekung.","Bercak membentuk cincin keunguan dengan daerah kekuningan di sekelilingnya.","Bagian daun di atas bercak dapat mengering dan patah."],"prevention":["Pilih benih sehat, tidak keropos dan tidak terluka.","Perbaiki drainase serta lakukan pergiliran tanaman bukan inang.","Jaga kebersihan pertanaman dari sisa tanaman sakit."],"first_steps":["Amati perubahan warna dan pola bercak, bukan warna daun secara keseluruhan saja.","Pisahkan bahan tanaman sakit dari bahan tanam sehat.","Bila serangan bertambah, konsultasikan pengendalian kepada POPT atau penyuluh; penggunaan pestisida harus sesuai label yang berlaku."],"confused_with":"Antraknosa juga dapat menimbulkan bercak putih. Cincin keunguan merupakan petunjuk pembanding, bukan kepastian diagnosis.","sources":[{"title":"Penyakit bercak ungu pada tanaman bawang merah dan pengendaliannya","publisher":"Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng","year":"2020","url":"https://distankan.bulelengkab.go.id/informasi/detail/artikel/penyakit-bercak-ungu-pada-tanaman-bawang-merah-dan-pengendaliannya-27"},{"title":"Budidaya bawang merah · bagian penyakit penting","publisher":"BRMP Banten, Kementerian Pertanian","year":"tahun dokumen tidak tercantum pada rujukan yang ditinjau","url":"https://banten.brmp.pertanian.go.id/storage/assets/uploads/file/GeY2HQf382EJXVJsYRiE9ZwRfFwnHSw5fL8twqWy.pdf#page=5"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=25","label":"Gambar 9 · halaman tercetak 15 (PDF 25)","credit":"Jacobsen/Shurleff, sebagaimana kredit dalam buku Balitsa (2005). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Bercak ungu / trotol","bercak ungu","trotol","purple blotch","Alternaria porri"],"source_title":"Penyakit bercak ungu pada tanaman bawang merah dan pengendaliannya","source_url":"https://distankan.bulelengkab.go.id/informasi/detail/artikel/penyakit-bercak-ungu-pada-tanaman-bawang-merah-dan-pengendaliannya-27"},{"doc_id":"PM-DISEASE-ANTRAKNOSA-001","title":"Antraknosa / otomatis","summary":"Kenali bercak putih yang membesar pada daun. Pada perkembangannya dapat terlihat massa spora merah muda hingga gelap.","content":"# Antraknosa / otomatis\n\nKenali bercak putih yang membesar pada daun. Pada perkembangannya dapat terlihat massa spora merah muda hingga gelap.\n\nPenyebab: Colletotrichum gloeosporioides.\n\n## Gejala yang diamati\n- Bercak putih kecil pada daun dapat membesar dan tampak cekung.\n- Pada bercak dapat terbentuk massa spora merah muda, lalu menggelap.\n- Daun yang rusak dapat patah atau rebah.\n\n## Pencegahan\n- Gunakan bahan tanam sehat dan sanitasi sisa tanaman sakit.\n- Atur jarak tanam dan drainase untuk mengurangi kelembapan berlebihan.\n- Lakukan pergiliran tanaman dan pemupukan berimbang.\n\n## Tindakan awal\n- Amati perkembangan bercak dan kondisi pertanaman setelah hujan.\n- Singkirkan bagian tanaman sakit sesuai arahan petugas setempat.\n- Bawa catatan gejala kepada POPT atau penyuluh sebelum menentukan pengendalian lanjutan.\n\n## Jangan tertukar\nJangan menyamakan semua bercak putih dengan antraknosa. Bercak ungu dan gangguan lain memerlukan pemeriksaan pembanding.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Budidaya bawang merah · antraknosa](https://banten.brmp.pertanian.go.id/storage/assets/uploads/file/GeY2HQf382EJXVJsYRiE9ZwRfFwnHSw5fL8twqWy.pdf#page=6) — BRMP Banten, Kementerian Pertanian, tahun dokumen tidak tercantum pada rujukan yang ditinjau.\n- [Pengamatan hama dan penyakit pada bawang merah di Subak Anyar Penglatan](https://distankan.bulelengkab.go.id/informasi/detail/berita/pengamatan-hama-dan-penyakit-pada-bawang-merah-di-subak-anyar-penglatan-39) — Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng, 2019.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Colletotrichum gloeosporioides","aliases":["antraknosa","otomatis","anthracnose"],"parts":["Daun"],"symptoms":["Bercak putih kecil pada daun dapat membesar dan tampak cekung.","Pada bercak dapat terbentuk massa spora merah muda, lalu menggelap.","Daun yang rusak dapat patah atau rebah."],"prevention":["Gunakan bahan tanam sehat dan sanitasi sisa tanaman sakit.","Atur jarak tanam dan drainase untuk mengurangi kelembapan berlebihan.","Lakukan pergiliran tanaman dan pemupukan berimbang."],"first_steps":["Amati perkembangan bercak dan kondisi pertanaman setelah hujan.","Singkirkan bagian tanaman sakit sesuai arahan petugas setempat.","Bawa catatan gejala kepada POPT atau penyuluh sebelum menentukan pengendalian lanjutan."],"confused_with":"Jangan menyamakan semua bercak putih dengan antraknosa. Bercak ungu dan gangguan lain memerlukan pemeriksaan pembanding.","sources":[{"title":"Budidaya bawang merah · antraknosa","publisher":"BRMP Banten, Kementerian Pertanian","year":"tahun dokumen tidak tercantum pada rujukan yang ditinjau","url":"https://banten.brmp.pertanian.go.id/storage/assets/uploads/file/GeY2HQf382EJXVJsYRiE9ZwRfFwnHSw5fL8twqWy.pdf#page=6"},{"title":"Pengamatan hama dan penyakit pada bawang merah di Subak Anyar Penglatan","publisher":"Dinas Pertanian, Ketahanan Pangan dan Perikanan Kabupaten Buleleng","year":"2019","url":"https://distankan.bulelengkab.go.id/informasi/detail/berita/pengamatan-hama-dan-penyakit-pada-bawang-merah-di-subak-anyar-penglatan-39"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=26","label":"Gambar 10 · halaman tercetak 16 (PDF 26)","credit":"Suhardi, dalam Udiarto, Setiawati & Suryaningsih, Balitsa (2005). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Antraknosa / otomatis","antraknosa","otomatis","anthracnose","Colletotrichum gloeosporioides"],"source_title":"Budidaya bawang merah · antraknosa","source_url":"https://banten.brmp.pertanian.go.id/storage/assets/uploads/file/GeY2HQf382EJXVJsYRiE9ZwRfFwnHSw5fL8twqWy.pdf#page=6"},{"doc_id":"PM-DISEASE-EMBUN-BULU-001","title":"Embun bulu / tepung palsu","summary":"Penyakit daun yang perlu dicermati pada kondisi lembap. Lapisan menyerupai bulu pada daun merupakan petunjuk pengamatan.","content":"# Embun bulu / tepung palsu\n\nPenyakit daun yang perlu dicermati pada kondisi lembap. Lapisan menyerupai bulu pada daun merupakan petunjuk pengamatan.\n\nPenyebab: Peronospora destructor (oomycete).\n\n## Gejala yang diamati\n- Daun tampak lebih pucat, lalu dapat menguning dan mengering.\n- Pada kondisi lembap dapat muncul lapisan bulu keabu-abuan hingga keunguan.\n- Kerusakan daun dapat meluas pada kondisi yang mendukung penyakit.\n\n## Pencegahan\n- Gunakan bahan tanam sehat dan kurangi sumber infeksi dari sisa tanaman sakit.\n- Jaga sirkulasi udara pertanaman serta drainase lahan.\n- Pantau daun saat kondisi lembap.\n\n## Tindakan awal\n- Periksa permukaan daun dan bandingkan dengan foto rujukan.\n- Catat perubahan gejala dan mintakan pemeriksaan POPT atau penyuluh.\n- Hindari menetapkan jenis penyakit atau memilih pestisida hanya dari warna lapisan pada daun.\n\n## Jangan tertukar\nEmbun bulu tidak sama dengan bercak ungu. Warna keunguan saja tidak cukup untuk membedakan keduanya.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Pengenalan hama dan penyakit pada tanaman bawang merah dan pengendaliannya · embun bulu](https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=27) — Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran, 2005.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Peronospora destructor (oomycete)","aliases":["embun bulu","tepung palsu","downy mildew"],"parts":["Daun"],"symptoms":["Daun tampak lebih pucat, lalu dapat menguning dan mengering.","Pada kondisi lembap dapat muncul lapisan bulu keabu-abuan hingga keunguan.","Kerusakan daun dapat meluas pada kondisi yang mendukung penyakit."],"prevention":["Gunakan bahan tanam sehat dan kurangi sumber infeksi dari sisa tanaman sakit.","Jaga sirkulasi udara pertanaman serta drainase lahan.","Pantau daun saat kondisi lembap."],"first_steps":["Periksa permukaan daun dan bandingkan dengan foto rujukan.","Catat perubahan gejala dan mintakan pemeriksaan POPT atau penyuluh.","Hindari menetapkan jenis penyakit atau memilih pestisida hanya dari warna lapisan pada daun."],"confused_with":"Embun bulu tidak sama dengan bercak ungu. Warna keunguan saja tidak cukup untuk membedakan keduanya.","sources":[{"title":"Pengenalan hama dan penyakit pada tanaman bawang merah dan pengendaliannya · embun bulu","publisher":"Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran","year":"2005","url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=27"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=28","label":"Gambar 11 · halaman tercetak 18 (PDF 28)","credit":"Sherf, dalam Udiarto, Setiawati & Suryaningsih, Balitsa (2005). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Embun bulu / tepung palsu","embun bulu","tepung palsu","downy mildew","Peronospora destructor (oomycete)"],"source_title":"Pengenalan hama dan penyakit pada tanaman bawang merah dan pengendaliannya · embun bulu","source_url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=27"},{"doc_id":"PM-DISEASE-STEMPHYLIUM-001","title":"Hawar daun Stemphylium","summary":"Bercak pucat pada daun dapat melebar dan menyatu hingga bagian yang rusak berwarna cokelat tua atau kehitaman.","content":"# Hawar daun Stemphylium\n\nBercak pucat pada daun dapat melebar dan menyatu hingga bagian yang rusak berwarna cokelat tua atau kehitaman.\n\nPenyebab: Stemphylium vesicarium.\n\n## Gejala yang diamati\n- Amati bercak awal berwarna kuning muda atau cokelat muda pada daun.\n- Bercak yang meluas dapat menyatu. Bagian yang rusak dapat menggelap dan membusuk.\n- Pada tanaman yang sedang berbunga, tangkai bunga yang terserang dapat mengering dan terkulai.\n\n## Pencegahan\n- Pilih bahan tanam yang sehat dan singkirkan sisa tanaman sakit dari lahan.\n- Pantau daun lebih sering ketika tajuk lama lembap atau banyak embun.\n- Pada pertanaman untuk benih biji, periksa daun dan tangkai bunga sejak awal pembungaan.\n\n## Tindakan awal\n- Catat letak dan perkembangan bercak pada beberapa tanaman.\n- Jika tanaman berbunga, periksa tangkai bunga yang mengering atau terkulai.\n- Tunjukkan foto dan catatan perkembangan gejala kepada POPT atau penyuluh sebelum memilih tindakan pengendalian.\n\n## Jangan tertukar\nHawar Stemphylium dapat muncul bersama bercak ungu. Warna bercak yang menggelap saja belum cukup untuk membedakan keduanya.\n\nReferensi edukasi, bukan diagnosis pasti. Gejala dapat saling menyerupai. Konsultasikan tanaman yang memburuk kepada POPT atau penyuluh; jangan menentukan pestisida hanya dari foto.\n\n## Sumber\n- [Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4](https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content) — Rosliani dkk., IAARD Press, Kementerian Pertanian, 2022.\n- [Pengenalan Hama dan Penyakit pada Tanaman Bawang Merah dan Pengendaliannya · bagian 2.2.5](https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=29) — Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran, 2005.\n\nRingkasan editorial SIMANTRI; belum divalidasi ahli. Bukan hasil pemeriksaan lapangan atau kerja sama resmi Dinas Pertanian.","metadata":{"catalogue":"pm-disease-v1","disease":{"scientific_name":"Stemphylium vesicarium","aliases":["stemphylium","ngelumpruk","leumpeuh","hawar daun stemphylium"],"parts":["Daun"],"symptoms":["Amati bercak awal berwarna kuning muda atau cokelat muda pada daun.","Bercak yang meluas dapat menyatu. Bagian yang rusak dapat menggelap dan membusuk.","Pada tanaman yang sedang berbunga, tangkai bunga yang terserang dapat mengering dan terkulai."],"prevention":["Pilih bahan tanam yang sehat dan singkirkan sisa tanaman sakit dari lahan.","Pantau daun lebih sering ketika tajuk lama lembap atau banyak embun.","Pada pertanaman untuk benih biji, periksa daun dan tangkai bunga sejak awal pembungaan."],"first_steps":["Catat letak dan perkembangan bercak pada beberapa tanaman.","Jika tanaman berbunga, periksa tangkai bunga yang mengering atau terkulai.","Tunjukkan foto dan catatan perkembangan gejala kepada POPT atau penyuluh sebelum memilih tindakan pengendalian."],"confused_with":"Hawar Stemphylium dapat muncul bersama bercak ungu. Warna bercak yang menggelap saja belum cukup untuk membedakan keduanya.","sources":[{"title":"Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4","publisher":"Rosliani dkk., IAARD Press, Kementerian Pertanian","year":"2022","url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content"},{"title":"Pengenalan Hama dan Penyakit pada Tanaman Bawang Merah dan Pengendaliannya · bagian 2.2.5","publisher":"Udiarto, Setiawati & Suryaningsih, Balai Penelitian Tanaman Sayuran","year":"2005","url":"https://repository.pertanian.go.id/server/api/core/bitstreams/2cae6926-4681-4cfc-b1dc-2219b18c474d/content#page=29"}],"photo_reference":{"url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content","label":"Gambar 31 · halaman tercetak 93 · gejala pada tangkai bunga","credit":"Sulastrini (2020), dikutip dalam Rosliani dkk. (2022). Izin penggunaan ulang belum dikonfirmasi."}}},"keywords":["Hawar daun Stemphylium","stemphylium","ngelumpruk","leumpeuh","hawar daun stemphylium","Stemphylium vesicarium"],"source_title":"Benih Biji Bawang Merah di Indonesia · bagian 6.2.5 dan 6.4","source_url":"https://repository.pertanian.go.id/server/api/core/bitstreams/4a250672-f833-42cc-83d5-35327f1d5e3e/content"}]'::jsonb) as item(doc_id text,title text,summary text,content text,keywords text[],source_title text,source_url text,metadata jsonb)
